type ExportAlert = { id: string; projectId: string; projectName: string; type: string; severity: string; message: string; currentValue: string; threshold: string; recommendedAction: string; acknowledged: boolean };
type ReviewZone = { north: number; south: number; east: number; west: number };
const ResponsiveContainer = ({ minWidth, minHeight, ...props }: ComponentProps<typeof RechartsResponsiveContainer>) => <RechartsResponsiveContainer {...props} minWidth={minWidth ?? 1} minHeight={minHeight ?? 1} />;

function stateNamesInReviewZone(zone: ReviewZone | null) {
  if (!zone) return [];
  return Object.entries(LEAFLET_STATE_COORDINATES).filter(([, [latitude, longitude]]) => latitude <= zone.north && latitude >= zone.south && longitude <= zone.east && longitude >= zone.west).map(([name]) => name);
}

function reviewZoneFromSearch() {
  const values = new URLSearchParams(window.location.search).get("reviewZone")?.split(",").map(Number);
  if (!values || values.length !== 4 || values.some(value => !Number.isFinite(value))) return null;
  const [north, south, east, west] = values;
  return north > south && east > west ? { north, south, east, west } : null;
}

function reviewZoneSearch(zone: ReviewZone | null) {
  return zone ? `?reviewZone=${[zone.north, zone.south, zone.east, zone.west].map(value => value.toFixed(3)).join(",")}` : "";
}

function downloadAlertCsv(alerts: ExportAlert[], filters: string) {
  const escape = (value: string | number | boolean) => `"${String(value).replaceAll('"', '""')}"`;
  const header = ["Alert ID", "Project ID", "Project", "Severity", "Alert Type", "Reason", "Current Value", "Threshold", "Recommended Attention Area", "Review State"];
  const rows = alerts.map(alert => [alert.id, alert.projectId, alert.projectName, alert.severity, alert.type, alert.message, alert.currentValue, alert.threshold, alert.recommendedAction, alert.acknowledged ? "Acknowledged" : "Open"]);
  const blob = new Blob([[header, ...rows].map(row => row.map(escape).join(",")).join("\n")], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "paimana-ai-filtered-alerts.csv"; anchor.click(); URL.revokeObjectURL(url);
  void filters;
}

async function downloadAlertPdf(alerts: ExportAlert[], filters: string) {
  const { jsPDF } = await import("jspdf");
  const report = new jsPDF({ unit: "pt", format: "a4" });
  let y = 48;
  const line = (text: string, size = 9, bold = false) => { report.setFont("helvetica", bold ? "bold" : "normal"); report.setFontSize(size); const wrapped = report.splitTextToSize(text, 500); if (y + wrapped.length * (size + 4) > 780) { report.addPage(); y = 48; } report.text(wrapped, 48, y); y += wrapped.length * (size + 4) + 7; };
  report.setTextColor(18, 59, 98); line("InfraNexus — Filtered Risk & Alert Operations Report", 16, true); report.setTextColor(67, 86, 106); line("Analytical outputs are not official Government of India decisions.", 9); line(`Applied filters: ${filters}. Matching alerts: ${alerts.length}.`, 9); y += 4;
  alerts.forEach((alert, index) => { report.setTextColor(25, 64, 95); line(`${index + 1}. ${alert.severity.toUpperCase()} — ${alert.type}`, 10, true); report.setTextColor(65, 82, 99); line(`${alert.projectId} · ${alert.projectName}`, 9); line(`${alert.message} Current: ${alert.currentValue}. Threshold: ${alert.threshold}.`, 9); line(`Analytical attention area: ${alert.recommendedAction} | Review state: ${alert.acknowledged ? "Acknowledged" : "Open"}.`, 9); y += 3; });
  report.save("infranexus-filtered-alerts-report.pdf");
}

async function downloadProjectRiskBrief(detail: any) {
  const { jsPDF } = await import("jspdf");
  const report = new jsPDF({ unit: "pt", format: "a4" });
  const project = detail.project;
  const prediction = detail.modelPrediction;
  const explanation = detail.modelExplanation;
  let y = 48;
  const line = (text: string, size = 9, bold = false) => { report.setFont("helvetica", bold ? "bold" : "normal"); report.setFontSize(size); const wrapped = report.splitTextToSize(text, 500); if (y + wrapped.length * (size + 4) > 780) { report.addPage(); y = 48; } report.text(wrapped, 48, y); y += wrapped.length * (size + 4) + 8; };
  report.setTextColor(18, 59, 98); line("InfraNexus — Project Risk Brief", 17, true); report.setTextColor(73, 95, 114); line("AI-generated analytical report — not an official Government of India decision.", 9); y += 5;
  report.setTextColor(22, 61, 95); line(`${project.name} (${project.id})`, 13, true); report.setTextColor(70, 89, 108); line(`${project.ministry} · ${project.sector} · ${project.state} · ${project.status}`, 9); line(`Overall risk: ${prediction?.overallRisk ?? project.overallRisk}/100 (${prediction?.riskCategory ?? project.riskCategory}). Cost risk: ${prediction?.costRisk ?? project.costRisk}. Schedule risk: ${prediction?.timeRisk ?? project.delayRisk}. Implementation risk: ${prediction?.implementationRisk ?? project.implementationRisk}.`, 9); line(`Approved cost: ${money(project.approvedCost)}. Revised cost: ${money(project.revisedCost)}. Predicted final cost: ${prediction?.predictedFinalCost ? money(prediction.predictedFinalCost) : money(project.revisedCost * (1 + project.predictedCostOverrun / 100))}.`, 9); line(`Physical progress: ${project.physicalProgress}%. Financial progress: ${project.financialProgress}%. Planned progress: ${project.plannedProgress}%. Expected delay: ${prediction?.predictedDelayMonths ?? project.delayMonths} months.`, 9); y += 4;
  report.setTextColor(22, 61, 95); line("Top analytical contributors", 11, true); report.setTextColor(70, 89, 108); (explanation?.positiveContributors ?? detail.contributors ?? []).slice(0, 5).forEach((item: any, index: number) => line(`${index + 1}. ${item.feature}: ${item.value ?? "—"}; contribution ${item.contribution ?? "—"}.`, 9));
  report.setTextColor(22, 61, 95); line("Active early warnings", 11, true); report.setTextColor(70, 89, 108); (detail.alerts ?? []).slice(0, 6).forEach((alert: any) => line(`${alert.severity}: ${alert.type}. ${alert.message}`, 9));
  report.setTextColor(22, 61, 95); line("Analytical attention areas", 11, true); report.setTextColor(70, 89, 108); (detail.recommendations ?? []).forEach((recommendation: string, index: number) => line(`${index + 1}. ${recommendation}`, 9));
  report.setTextColor(92, 108, 123); line(`Generated: ${new Date().toLocaleString()}. Model: ${prediction?.modelVersion ?? "v1"}.`, 8);
  report.save(`infranexus-project-risk-brief-${project.id}.pdf`);
}

