  if (!overview.data) return <div className="grid min-h-[60vh] place-items-center"><div className="max-w-md rounded-xl border border-dashed border-[#cbd9e4] bg-[#f7fafc] p-5 text-center text-sm text-[#5e7385]">No portfolio profile is currently available for this governed demonstration workspace.</div></div>;
