function RiskHeatmap({ rows }: { rows: Array<{ sector: string; total: number; cells: Array<{ risk: string; count: number }> }> }) {
  const [, setLocation] = useLocation();
  const colorFor = (risk: string, ratio: number) => risk === "Critical" ? `rgba(202, 69, 85, ${0.14 + ratio * 0.72})` : risk === "High" ? `rgba(213, 125, 43, ${0.14 + ratio * 0.72})` : risk === "Moderate" ? `rgba(226, 168, 52, ${0.14 + ratio * 0.65})` : `rgba(52, 142, 105, ${0.14 + ratio * 0.62})`;
  return <Panel title="Sector × risk heatmap" subtitle="Click a cell to open the matching project segment in the Explorer." action={<span className="text-[10px] font-medium text-[#658096]">Synthetic portfolio distribution</span>}><div className="overflow-x-auto"><div className="min-w-[660px]"><div className="grid grid-cols-[170px_repeat(4,1fr)] gap-1.5 text-[10px]"><span className="px-2 py-2 font-semibold uppercase tracking-[0.12em] text-[#718397]">Sector</span>{["Low", "Moderate", "High", "Critical"].map(risk => <span key={risk} className="px-2 py-2 text-center font-semibold uppercase tracking-[0.12em] text-[#718397]">{risk}</span>)}{rows.slice(0, 8).map(row => <Fragment key={row.sector}><span className="flex items-center px-2 text-xs font-medium text-[#38566f]">{row.sector}</span>{row.cells.map(cell => { const ratio = row.total ? cell.count / row.total : 0; return <button key={`${row.sector}-${cell.risk}`} aria-label={`Open ${cell.count} ${cell.risk} ${row.sector} projects`} onClick={() => setLocation(`/explorer?sector=${encodeURIComponent(row.sector)}&risk=${cell.risk}&monthStart=Jan%202026&monthEnd=Aug%202026`)} className="rounded-md border border-white/70 px-2 py-3 text-center transition-transform duration-200 hover:-translate-y-0.5 hover:shadow-md focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#245f95]" style={{ backgroundColor: colorFor(cell.risk, ratio) }}><b className="block text-sm text-[#163b5e]">{cell.count}</b><span className="mt-0.5 block text-[9px] text-[#34536c]">{Math.round(ratio * 100)}%</span></button>; })}</Fragment>)}</div></div></div></Panel>;
}

type DrilldownRow = { id: string; name: string; ministry: string; sector: string; state: string; physicalProgress: number; financialProgress: number; overallRisk: number; riskCategory: string; updatedAt: string };
function downloadDrilldownCsv(rows: DrilldownRow[], label: string) { const header = ["Project ID", "Project", "Ministry", "Sector", "State", "Physical Progress", "Financial Progress", "Overall Risk", "Risk Category", "Updated"]; const body = rows.map(row => [row.id, row.name, row.ministry, row.sector, row.state, `${row.physicalProgress}%`, `${row.financialProgress}%`, row.overallRisk, row.riskCategory, row.updatedAt]); const csv = [header, ...body].map(row => row.map(value => `"${String(value).replaceAll('"', '""')}"`).join(",")).join("\n"); const blob = new Blob([csv], { type: "text/csv;charset=utf-8" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `paimana-ai-heatmap-${label.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}.csv`; anchor.click(); URL.revokeObjectURL(url); }
async function downloadDrilldownPdf(rows: DrilldownRow[], label: string) { const { jsPDF } = await import("jspdf"); const report = new jsPDF({ unit: "pt", format: "a4" }); let y = 48; const line = (text: string, size = 9, bold = false) => { report.setFont("helvetica", bold ? "bold" : "normal"); report.setFontSize(size); const wrapped = report.splitTextToSize(text, 500); if (y + wrapped.length * (size + 4) > 780) { report.addPage(); y = 48; } report.text(wrapped, 48, y); y += wrapped.length * (size + 4) + 7; }; report.setTextColor(18, 59, 98); line("InfraNexus — Heatmap drill-through report", 16, true); report.setTextColor(72, 93, 112); line(`Segment: ${label}. Matching projects: ${rows.length}. Analytical report, not an official decision.`, 9); rows.forEach((row, index) => { report.setTextColor(26, 64, 95); line(`${index + 1}. ${row.id} — ${row.name}`, 10, true); report.setTextColor(72, 93, 112); line(`${row.sector} · ${row.state} · ${row.riskCategory} risk ${row.overallRisk}/100 · ${row.physicalProgress}% physical / ${row.financialProgress}% financial`, 9); }); report.save(`infranexus-heatmap-${label.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}.pdf`); }

function DashboardQuery() {
  const [, setLocation] = useLocation();
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState<{ answer: string; sources: string[] } | null>(null);
  const ask = trpc.portfolio.ask.useMutation({ onSuccess: value => setResponse(value), onError: () => setResponse({ answer: "Insufficient project data available.", sources: [] }) });
  const submit = (value = prompt) => { const normalized = value.trim(); if (!normalized) return; setPrompt(normalized); ask.mutate({ question: normalized }); };
  return <Panel title="Conversational risk & alert search" subtitle="Ask a grounded question. Answers are constrained to the Synthetic Demonstration Dataset and controlled alert rules." action={<Bot className="size-4 text-[#3d719c]" />}><div className="flex flex-col gap-3 lg:flex-row"><div className="relative flex-1"><BrainCircuit className="absolute left-3 top-3 size-4 text-[#6d849b]" /><Input value={prompt} onChange={event => setPrompt(event.target.value)} onKeyDown={event => { if (event.key === "Enter") submit(); }} className="border-[#cfdae5] pl-9" placeholder="For example: Show critical projects in Maharashtra or list high-priority alerts." /></div><Button className="bg-[#143b62] hover:bg-[#0f3153]" disabled={ask.isPending || !prompt.trim()} onClick={() => submit()}>{ask.isPending ? "Searching…" : "Ask portfolio"}</Button></div><div className="mt-3 flex flex-wrap gap-2">{["Show critical projects in Maharashtra", "What are the highest-risk projects?", "List current high-priority alerts", "Which projects have high expenditure but low physical progress?"].map(example => <button key={example} onClick={() => submit(example)} className="rounded-full border border-[#d6e3ef] bg-[#f7fafc] px-3 py-1.5 text-[11px] font-medium text-[#49708e] transition-colors hover:bg-[#edf5fb]">{example}</button>)}</div>{response ? <div className="mt-4 rounded-lg border border-[#d7e5ef] bg-[#f6faff] p-4"><p className="whitespace-pre-wrap text-xs leading-6 text-[#395b76]">{response.answer.replaceAll("**", "")}</p>{response.sources.length ? <div className="mt-3 border-t border-[#dce7f0] pt-2"><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-[#6b8194]">Grounded sources</p><div className="mt-2 flex flex-wrap gap-2">{response.sources.map(id => <a key={id} href={`/projects/${id}`} className="rounded-md border border-[#bed4e6] bg-white px-2 py-1 text-[10px] font-semibold text-[#2d6594] hover:bg-[#eef6fc]">Open {id} ↗</a>)}</div></div> : null}</div> : null}</Panel>;
}

function DashboardQueryCompact() {
  const [, setLocation] = useLocation();
  const [prompt, setPrompt] = useState("");
  const [response, setResponse] = useState<{ answer: string; sources: string[] } | null>(null);
  const validationQuestion = useMemo(() => new URLSearchParams(window.location.search).get("assistantQuestion")?.trim() ?? "", []);
  const askedFromQuery = useRef(false);
  const suggestions = ["What are you?", "Show critical projects in Maharashtra", "List current high-priority alerts", "How does the what-if simulator calculate risk?"];
  const ask = trpc.portfolio.ask.useMutation({ onSuccess: value => setResponse(value), onError: () => setResponse({ answer: "I could not reach the assistant right now. Please try again or open the full Assistant workspace.", sources: [] }) });
  const submit = (value = prompt) => { const normalized = value.trim(); if (!normalized) return; setPrompt(normalized); ask.mutate({ question: normalized }); };
  useEffect(() => { if (validationQuestion && !askedFromQuery.current) { askedFromQuery.current = true; setPrompt(validationQuestion); ask.mutate({ question: validationQuestion }); } }, [ask, validationQuestion]);
  return <Panel title="Conversational risk & alert search" className="paimana-dashboard-query" action={<Button variant="outline" size="sm" className="h-7 border-[#c8d9e8] text-[11px] text-[#2d628d]" onClick={() => setLocation("/assistant")}>Open full assistant <ChevronRight className="ml-1 size-3" /></Button>}><div className="flex flex-col gap-3 lg:flex-row"><div className="relative flex-1"><BrainCircuit className="absolute left-3 top-3 size-4 text-[#6d849b]" /><Input value={prompt} onChange={event => setPrompt(event.target.value)} onKeyDown={event => { if (event.key === "Enter") submit(); }} className="border-[#cfdae5] pl-9" placeholder="Ask a quick question about risks, alerts, or the simulator…" /></div><Button className="bg-[#143b62] hover:bg-[#0f3153]" disabled={ask.isPending || !prompt.trim()} onClick={() => submit()}>{ask.isPending ? "Thinking…" : "Ask InfraNexus"}</Button></div><div className="mt-3 flex flex-wrap gap-2">{suggestions.map(example => <button key={example} onClick={() => submit(example)} className="rounded-full border border-[#d6e3ef] bg-[#f7fafc] px-3 py-1.5 text-[11px] font-medium text-[#49708e] transition-colors hover:bg-[#edf5fb]">{example}</button>)}</div>{response ? <div className="paimana-dashboard-assistant-response mt-3 rounded-lg border border-[#d7e5ef] bg-[#f6faff] p-3"><p className="whitespace-pre-wrap text-xs leading-5 text-[#395b76]">{response.answer.replaceAll("**", "")}</p>{response.sources.length ? <div className="mt-3 border-t border-[#34536e] pt-2.5"><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-[#7fa7c6]">Grounded sources</p><div className="mt-2 flex flex-wrap gap-2">{response.sources.map(id => <a key={id} href={`/projects/${id}`} className="rounded-md border border-[#4f7898] bg-[#183852] px-2 py-1 text-[10px] font-semibold text-[#d7eaf8] hover:bg-[#23516f]">Open {id} ↗</a>)}</div></div> : null}</div> : null}</Panel>;
}

