  if (coordinates.isError) return <><PageHeader eyebrow="Authorised spatial intelligence" title="Risk map" /><Disclaimer /><Panel title="Coordinate register unavailable"><div role="alert" className="rounded-lg border border-[#e5c8c4] bg-[#fff7f5] p-4 text-sm text-[#8b4b45]">The governed coordinate register could not be loaded, so no project markers are being shown. <button onClick={() => coordinates.refetch()} className="font-semibold underline">Retry</button></div></Panel></>;
  const activeCoordinates = coordinates.data?.filter(record => Number.isFinite(Number(record.latitude)) && Number.isFinite(Number(record.longitude))) ?? [];
